  ('211c55df-7338-5814-bf26-32fc9abf23a9'::uuid,1,'Let the group give you three ridiculous job titles. Pick one and explain why you are qualified in ten seconds. Or drink.',lower(regexp_replace('Let the group give you three ridiculous job titles. Pick one and explain why you are qualified in ten seconds. Or drink.','[^[:alnum:]'']+',' ','g')),'{"curationVersion":"dare-or-pour-playable-v2","playable":true}'::jsonb,'published','Dare or Pour playable V2 new challenge'),
