-- Recovered from the linked project's Supabase migration history.

-- Dare or Pour playable V2: 220 active challenges (154 new), 1,734 preserved archived challenges.
begin;

on conflict(id) do nothing;

on conflict(item_id,version) do nothing;

create temporary table decked_dare_or_pour_v2_active(item_id uuid primary key,category_id text not null,sort_order integer not null,body text not null,metadata jsonb not null,revised boolean not null) on commit drop;


do $$ declare matched integer; begin select count(*) into matched from public.content_items item join decked_dare_or_pour_v2_active selected on selected.item_id=item.id where item.game_id='do-or-drink'; if matched<>220 then raise exception 'Dare or Pour V2 inventory mismatch: expected 220 IDs, found %',matched; end if; end $$;

update public.content_items set lifecycle_status='archived',updated_at=now() where game_id='do-or-drink';

update public.content_items item set lifecycle_status='active',updated_at=now() from decked_dare_or_pour_v2_active selected where item.id=selected.item_id and item.game_id='do-or-drink';

update public.content_item_categories set enabled=false where game_id='do-or-drink';


create temporary table decked_dare_or_pour_v2_revisions on commit drop as select selected.*,item.current_version+1 next_version from decked_dare_or_pour_v2_active selected join public.content_items item on item.id=selected.item_id where selected.revised;

update public.content_item_versions version set editorial_status='superseded' from decked_dare_or_pour_v2_revisions revised where version.item_id=revised.item_id and version.version=(select published_version from public.content_items where id=revised.item_id);


update public.content_items item set current_version=revised.next_version,published_version=revised.next_version,updated_at=now() from decked_dare_or_pour_v2_revisions revised where item.id=revised.item_id;

update public.content_item_versions version set metadata=coalesce(version.metadata,'{}'::jsonb)||selected.metadata from decked_dare_or_pour_v2_active selected join public.content_items item on item.id=selected.item_id where not selected.revised and version.item_id=item.id and version.version=item.published_version;

update public.content_releases set status='superseded' where game_id='do-or-drink' and status='published';


delete from public.content_release_items where release_id='244248a1-6cd5-5045-a11b-fe121ab6db7e'::uuid;


commit;
